// Extract the inputs and expectations of the pinned live-provider tests. No
// requests are issued and no provider responses are generated by this tool.
import fs from "node:fs";
import path from "node:path";
import { createRequire } from "node:module";
import { execFileSync } from "node:child_process";
import { createHash } from "node:crypto";

const repo = path.resolve(import.meta.dirname, "..");
const upstream = path.resolve(
	repo,
	process.env.PONDER_UPSTREAM ?? "../ponder-upstream",
);
const require = createRequire(path.join(upstream, "package.json"));
const ts = require("typescript");
const ledger = JSON.parse(
	fs.readFileSync(path.join(repo, "parity/test-ledger.json")),
);
const revision = execFileSync("git", ["-C", upstream, "rev-parse", "HEAD"], {
	encoding: "utf8",
}).trim();
if (revision !== ledger.baseline.revision)
	throw Error("Unexpected upstream revision");
const selected = new Set([
	"348a8e37b07b6dc18282",
	"6e0331aa610922520c57",
	"d650131ba080274e5537",
	"f7bd5146724fd30daebf",
	"ec36e43b4edbccdd66bd",
	"4986ab39680c8e7a4ac7",
	"42c60199315b737e0f1c",
	"4a1e21d4dcfea25650ed",
	"a5c165fcfffd635850d0",
	"70a6963becb25618fa7c",
	"97acfa90ed9347c67690",
	"f9064819749ec8f29669",
	"3d3fd5270ec61a56ac1b",
	"b5713ed2730e0f1645ab",
	"4fe5b0a1e635d75c7425",
	"c88fe611a7ecaf0ee90d",
	"51499e4858745db713da",
]);
function parse(name, text) {
	return ts.createSourceFile(name, text, ts.ScriptTarget.Latest, true);
}
function literal(node, vars) {
	if (ts.isNumericLiteral(node) || ts.isBigIntLiteral(node))
		return Number(node.text.replaceAll("_", "").replace(/n$/, ""));
	if (ts.isStringLiteral(node)) return node.text;
	if (node.kind === ts.SyntaxKind.TrueKeyword) return true;
	if (ts.isIdentifier(node) && Object.hasOwn(vars, node.text))
		return vars[node.text];
	if (ts.isArrayLiteralExpression(node))
		return node.elements.map((v) => literal(v, vars));
	if (ts.isObjectLiteralExpression(node))
		return Object.fromEntries(
			node.properties.map((p) => [
				p.name.text,
				literal(p.initializer ?? p.name, vars),
			]),
		);
	if (ts.isCallExpression(node) && node.expression.getText() === "numberToHex")
		return "0x" + literal(node.arguments[0], vars).toString(16);
	if (ts.isBinaryExpression(node)) {
		const a = literal(node.left, vars),
			b = literal(node.right, vars);
		switch (node.operatorToken.kind) {
			case ts.SyntaxKind.PlusToken:
				return a + b;
			case ts.SyntaxKind.MinusToken:
				return a - b;
			case ts.SyntaxKind.SlashToken:
				return Math.trunc(a / b);
		}
	}
	throw Error("Unsupported source value: " + node.getText());
}
function declarations(file) {
	return file.statements
		.filter(ts.isVariableStatement)
		.flatMap((s) => [...s.declarationList.declarations]);
}
function firstCall(node, name) {
	if (ts.isCallExpression(node) && node.expression.getText() === name)
		return node;
	return ts.forEachChild(node, (child) => firstCall(child, name));
}
const base = "packages/utils/src/_test/";
const common = {};
const helpers = fs.readFileSync(path.join(upstream, base, "utils.ts"), "utf8");
for (const v of declarations(parse("utils.ts", helpers))) {
	if (["UNI", "WETH", "fromBlock"].includes(v.name.text))
		common[v.name.text] = literal(v.initializer, common);
}
const cases = [];
for (const t of ledger.tests.filter((t) => selected.has(t.id))) {
	const text = fs.readFileSync(path.join(upstream, t.source_file), "utf8");
	if (
		createHash("sha256").update(text).digest("hex") !== t.source_sha256 ||
		!text.includes(t.test_source)
	)
		throw Error(t.id);
	const file = parse(t.source_file, text),
		vars = { ...common };
	let endpoint;
	for (const v of declarations(file)) {
		if (v.name.text === "request") {
			const arg = v.initializer.arguments[0];
			endpoint = ts.isStringLiteral(arg)
				? { url: arg.text }
				: { env: arg.getText().match(/^process\.env\.(RPC_URL_\w+)!$/)[1] };
		} else vars[v.name.text] = literal(v.initializer, vars);
	}
	const call = parse("case.ts", t.test_source).statements[0].expression;
	const body = call.arguments.at(-1).body;
	for (const v of declarations(body))
		if (v.name.text === "params") vars.params = literal(v.initializer, vars);
	const request = literal(firstCall(body, "request").arguments[0], vars);
	const expect = {};
	const statements = body.statements.filter(
		(s) => ts.isExpressionStatement(s) && firstCall(s, "expect"),
	);
	if (statements.length !== t.assertions.length)
		throw Error("Lost source assertion: " + t.id);
	for (const s of statements) {
		const assertion = s.expression,
			actual = firstCall(assertion, "expect").arguments[0].getText(),
			method = assertion.expression.name.text;
		const arg = assertion.arguments[0];
		switch (actual + "." + method) {
			case "error.toBeInstanceOf":
				expect.errorClass = arg.text;
				break;
			case "JSON.stringify(error).includes":
				expect.message = literal(arg, vars);
				break;
			case "logs.toHaveLength":
				expect.logs = literal(arg, vars);
				break;
			case "retry.toStrictEqual":
				expect.plan = literal(arg, vars);
				break;
			case "retry.shouldRetry.toBe":
				expect.shouldRetry = literal(arg, vars);
				break;
			case "retry.ranges.toHaveLength":
				expect.rangeCount = literal(arg, vars);
				break;
			case "retry.ranges![0].toStrictEqual":
				expect.firstRange = literal(arg, vars);
				break;
			default:
				throw Error("Unsupported source assertion: " + s.getText());
		}
	}
	cases.push({
		id: t.id,
		name: t.full_name,
		provider: path.basename(t.source_file, ".test.ts"),
		...endpoint,
		request,
		expect,
		assertionCount: statements.length,
	});
}
if (cases.length !== selected.size)
	throw Error("Incomplete provider case inventory");
// viem translates recognized JSON-RPC codes into RpcError subclasses.
// A provider-specific JSON-RPC code retains its raw RpcRequestError class.
const viem = require("viem");
const viemRoot = path.dirname(require.resolve("viem/package.json"));
const dispatch = fs.readFileSync(
	path.join(viemRoot, "_esm/utils/buildRequest.js"),
	"utf8",
);
const rpcErrorCodes = [...dispatch.matchAll(/case (\w+)(\.code)?:/g)].map(
	([, name, field]) => (field ? viem[name].code : Number(name)),
);
if (
	!rpcErrorCodes.length ||
	rpcErrorCodes.some((code) => !Number.isSafeInteger(code))
)
	throw Error("Unexpected viem RPC dispatch");
const output =
		JSON.stringify({ revision, rpcErrorCodes, cases }, null, 2) + "\n",
	dest = path.join(repo, "testdata/rpc/provider-policy-cases.json");
if (process.argv.includes("--write")) fs.writeFileSync(dest, output);
else if (fs.readFileSync(dest, "utf8") !== output)
	throw Error("Provider fixtures differ from the source assertions");
